pub struct EventData {
    /// Unique identifier for this event.
    #[serde(rename = "event_ticker")]
    pub event_ticker: String,
    /// Unique identifier for the series this event belongs to.
    #[serde(rename = "series_ticker")]
    pub series_ticker: String,
    /// Shortened descriptive title for the event.
    #[serde(rename = "sub_title")]
    pub sub_title: String,
    /// Full title of the event.
    #[serde(rename = "title")]
    pub title: String,
    /// Collateral-return netting type for this event: `MECNET` for mutually exclusive markets, `DIRECNET` for directional netting, or an empty string for no collateral-return netting.
    /// Netting applies within this event, not across all events in its series, and also requires netting to be enabled for the trading account or subtrader.
    /// Use `with_nested_markets=true` to retrieve the markets associated with each event.
    #[serde(rename = "collateral_return_type")]
    pub collateral_return_type: String,
    /// True when `collateral_return_type` is `MECNET`: at most one market in this event can resolve to 'yes'.
    /// False for both `DIRECNET` and an empty collateral-return type. A false value does not mean collateral-return netting is unavailable. Use `collateral_return_type` to distinguish these cases.
    #[serde(rename = "mutually_exclusive")]
    pub mutually_exclusive: bool,
    /// Event category (deprecated, use series-level category instead).
    /// Deprecated upstream; retained for compatibility and optional on decode.
    #[serde(rename = "category", default, skip_serializing_if = "Option::is_none")]
    pub category: Option<String>,
    /// The specific date this event is based on. Only filled when the event uses a date strike (mutually exclusive with strike_period).
    #[serde(
        rename = "strike_date",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub strike_date: Option<String>,
    /// The time period this event covers (e.g., 'week', 'month'). Only filled when the event uses a period strike (mutually exclusive with strike_date).
    #[serde(
        rename = "strike_period",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub strike_period: Option<String>,
    /// Array of markets associated with this event. Only populated when 'with_nested_markets=true' is specified in the request.
    #[serde(rename = "markets", default, skip_serializing_if = "Option::is_none")]
    pub markets: Option<Vec<Market>>,
    /// Additional metadata for the event.
    #[serde(
        rename = "product_metadata",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub product_metadata: Option<std::collections::BTreeMap<String, serde_json::Value>>,
    /// The official sources used for the determination of markets within this event. Methodology is defined in the rulebook.
    #[serde(
        rename = "settlement_sources",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub settlement_sources: Option<Vec<SettlementSource>>,
    /// Timestamp of when this event's metadata was last updated.
    #[serde(
        rename = "last_updated_ts",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub last_updated_ts: Option<String>,
    /// Fee type override for this event. When present, takes precedence over the series-level fee for this event's markets.
    #[serde(
        rename = "fee_type_override",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub fee_type_override: Option<String>,
    /// Fee multiplier override for this event. Paired with fee_type_override.
    #[serde(
        rename = "fee_multiplier_override",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub fee_multiplier_override: Option<serde_json::Number>,
    /// API field `exchange_index`.
    #[serde(
        rename = "exchange_index",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub exchange_index: Option<ExchangeIndex>,
}

/// Series wire representation from the official specification.
#[derive(Clone, Serialize, Deserialize, Debug)]
pub struct Series {
    /// Ticker that identifies this series.
    #[serde(rename = "ticker")]
    pub ticker: String,
    /// Description of the frequency of the series. There is no fixed value set here, but will be something human-readable like weekly, daily, one-off.
    #[serde(rename = "frequency")]
    pub frequency: String,
    /// Title describing the series. For full context use you should use this field with the title field of the events belonging to this series.
    #[serde(rename = "title")]
    pub title: String,
    /// Category is the primary category of this series.
    #[serde(rename = "category")]
    pub category: String,
    /// Categories is the list of discovery categories for this series. The `category` filter on Get Series List matches any entry in this list. May be empty.
    #[serde(rename = "categories")]
    pub categories: Vec<String>,
    /// Tags specifies the subjects that this series relates to, multiple series from different categories can have the same tags.
    #[serde(rename = "tags", default, skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
    /// SettlementSources specifies the official sources used for the determination of markets within the series. Methodology is defined in the rulebook.
    #[serde(
        rename = "settlement_sources",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub settlement_sources: Option<Vec<SettlementSource>>,
    /// ContractUrl provides a direct link to the original filing of the contract which underlies the series.
    #[serde(rename = "contract_url")]
    pub contract_url: String,
    /// ContractTermsUrl is the URL to the current terms of the contract underlying the series.
    #[serde(rename = "contract_terms_url")]
    pub contract_terms_url: String,
    /// Internal product metadata of the series.
    #[serde(
        rename = "product_metadata",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub product_metadata: Option<std::collections::BTreeMap<String, serde_json::Value>>,
    /// FeeType is a string representing the series' fee structure. Fee structures can be found at <https://kalshi.com/docs/kalshi-fee-schedule.pdf>. 'quadratic' is described by the General Trading Fees Table, 'quadratic_with_maker_fees' is described by the General Trading Fees Table with maker fees described in the Maker Fees section, 'quadratic_with_combo_maker_fees' is the same maker-fee structure with a 0.5 maker multiplier instead of 0.25, 'flat' is described by the Specific Trading Fees Table.
    #[serde(rename = "fee_type")]
    pub fee_type: FeeType,
    /// FeeMultiplier is a floating point multiplier applied to the fee calculations.
    #[serde(rename = "fee_multiplier")]
    pub fee_multiplier: serde_json::Number,
    /// AdditionalProhibitions is a list of additional trading prohibitions for this series.
    #[serde(
        rename = "additional_prohibitions",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub additional_prohibitions: Option<Vec<String>>,
    /// String representation of the total number of contracts traded across all events in this series.
    #[serde(rename = "volume_fp", default, skip_serializing_if = "Option::is_none")]
    pub volume_fp: Option<FixedPointCount>,
    /// Timestamp of when this series' metadata was last updated.
    #[serde(
        rename = "last_updated_ts",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub last_updated_ts: Option<String>,
    /// API field `exchange_index`.
    #[serde(
        rename = "exchange_index",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub exchange_index: Option<ExchangeIndex>,
}
impl Default for Series {
    fn default() -> Self {
        Self {
            ticker: Default::default(),
            frequency: Default::default(),
            title: Default::default(),
            category: Default::default(),
            categories: Default::default(),
            tags: Default::default(),
            settlement_sources: Default::default(),
            contract_url: Default::default(),
            contract_terms_url: Default::default(),
            product_metadata: Default::default(),
            fee_type: Default::default(),
            fee_multiplier: serde_json::Number::from(0),
            additional_prohibitions: Default::default(),
            volume_fp: Default::default(),
            last_updated_ts: Default::default(),
            exchange_index: Default::default(),
        }
    }
}

